// Phase 3 (INTER), G7: the FIRST COMPOUND (2-reference) PIXELS.
//
// A hierarchical-GOP stream (lag-in-frames=10, auto-alt-ref) whose frame at
// decode index 6 (order hint 4) contains a compound block:
//   ref0 = LAST (fwd), ref1 = ALTREF (bwd), inter_mode = NEAREST_NEARESTMV,
//   compound type = COMPOUND_AVERAGE, skip = 1 (pure motion compensation, no
//   residual), MVs with sub-pel on both axes.
// (Confirmed by the conformant SW reference decoder.) Masked / dist-wtd / jnt
// compound were disabled at encode so every compound block is AVERAGE.
//
// This reconstructs that compound block bit-exact vs the SW reference pre-filter
// recon using the PROVEN Harbor HW compound kernels, mirroring the SW
// _compoundPredict / _avgDistWtdBlend geometry EXACTLY:
//   * each reference -> a 16-bit CONV_BUF prediction via HarborInterConvolveD16
//     (the !doAverage producer, av1_dist_wtd_convolve, round_0=3, round_1=7,
//     offset 6144).
//   * the two CONV_BUF buffers -> the final 8-bit pixels via HarborCompoundBlend
//     mode 0 (AVERAGE): tmp=(src0+src1)>>1, tmp-=6144, out=clip((tmp+8)>>4).
// The per-plane reference patches, fractional phases, block geometry and the
// golden pre-filter pixels below are all captured from the SW reference decode
// of frame 6 (which resolves the full DPB, block MV/refs and recon).

const _numPlanes = 3;

// Per-plane [sx, sy, ox, oy, pbw, pbh] from the SW reference decode.
const _geom = <List<int>>[
  [0, 0, 0, 32, 16, 32],
  [1, 1, 0, 16, 8, 16],
  [1, 1, 0, 16, 8, 16],
];

// Per-plane reference-A / reference-B fractional phases [subX, subY].
const _fracA = <List<int>>[
  [4, 0],
  [2, 8],
  [2, 8],
];
const _fracB = <List<int>>[
  [12, 0],
  [14, 8],
  [14, 8],
];

// Per-plane reference sample patches (edge-replicated, packed row-major
// (pr*(pbw+7)+pc)*8 exactly as the DUT consumes) as BigInt strings.
const _patchA = <String>[
  '',
  '',
  '',
];
const _patchB = <String>[
  '',
  '',
  '',
];

