void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  test('inter compound: COMPOUND_AVERAGE recon bit-exact vs SW', () async {
    final clk = SimpleClockGenerator(10).clk;

    // Build one CONV_BUF producer per reference lane + one blend, per distinct
    // plane block size, wired combinationally: patch -> d16 -> blend -> pixels.
    final d16aByKey = <int, HarborInterConvolveD16>{};
    final d16bByKey = <int, HarborInterConvolveD16>{};
    final blendByKey = <int, HarborCompoundBlend>{};
    final paByKey = <int, Logic>{}, pbByKey = <int, Logic>{};
    final faxByKey = <int, Logic>{}, fayByKey = <int, Logic>{};
    final fbxByKey = <int, Logic>{}, fbyByKey = <int, Logic>{};

    for (var p = 0; p < _numPlanes; p++) {
      final g = _geom[p];
      final pbw = g[4], pbh = g[5];
      final key = pbw * 1000 + pbh;
      if (d16aByKey.containsKey(key)) continue;
      final d16a = HarborInterConvolveD16(width: pbw, height: pbh);
      final d16b = HarborInterConvolveD16(width: pbw, height: pbh);
      final blend = HarborCompoundBlend(width: pbw, height: pbh);
      final pa = Logic(name: 'pa_$key', width: (pbw + 7) * (pbh + 7) * 8);
      final pb = Logic(name: 'pb_$key', width: (pbw + 7) * (pbh + 7) * 8);
      final fax = Logic(name: 'fax_$key', width: 4);
      final fay = Logic(name: 'fay_$key', width: 4);
      final fbx = Logic(name: 'fbx_$key', width: 4);
      final fby = Logic(name: 'fby_$key', width: 4);
      d16a.input('patch').srcConnection! <= pa;
      d16a.input('frac_x').srcConnection! <= fax;
      d16a.input('frac_y').srcConnection! <= fay;
      d16b.input('patch').srcConnection! <= pb;
      d16b.input('frac_x').srcConnection! <= fbx;
      d16b.input('frac_y').srcConnection! <= fby;
      // Wire the two CONV_BUF producers straight into the AVERAGE blend.
      blend.input('src0').srcConnection! <= d16a.output('conv');
      blend.input('src1').srcConnection! <= d16b.output('conv');
      blend.input('mask').srcConnection! <= Const(0, width: pbw * pbh * 7);
      blend.input('fwd').srcConnection! <= Const(8, width: 5);
      blend.input('bck').srcConnection! <= Const(8, width: 5);
      blend.input('use_dist_wtd').srcConnection! <= Const(0, width: 1);
      blend.input('mode').srcConnection! <= Const(0, width: 2);
      d16aByKey[key] = d16a;
      d16bByKey[key] = d16b;
      blendByKey[key] = blend;
      paByKey[key] = pa;
      pbByKey[key] = pb;
      faxByKey[key] = fax;
      fayByKey[key] = fay;
      fbxByKey[key] = fbx;
      fbyByKey[key] = fby;
    }

    for (final m in d16aByKey.values) {
      await m.build();
    }
    for (final m in d16bByKey.values) {
      await m.build();
    }
    for (final m in blendByKey.values) {
      await m.build();
    }

    Simulator.setMaxSimTime(200000000);
    unawaited(Simulator.run());
    await clk.nextPosedge;

    var diffTotal = 0;
    for (var p = 0; p < _numPlanes; p++) {
      final g = _geom[p];
      final pbw = g[4], pbh = g[5];
      final key = pbw * 1000 + pbh;

      paByKey[key]!.inject(BigInt.parse(_patchA[p]));
      pbByKey[key]!.inject(BigInt.parse(_patchB[p]));
      faxByKey[key]!.inject(_fracA[p][0]);
      fayByKey[key]!.inject(_fracA[p][1]);
      fbxByKey[key]!.inject(_fracB[p][0]);
      fbyByKey[key]!.inject(_fracB[p][1]);
      await clk.nextPosedge;

      final out = blendByKey[key]!.output('out').value;
      final gold = _golden[p];
      for (var y = 0; y < pbh; y++) {
        for (var x = 0; x < pbw; x++) {
          final idx = y * pbw + x;
          final px = out.getRange(idx * 8, idx * 8 + 8).toInt();
          if (px != gold[idx]) diffTotal++;
        }
      }
    }

    expect(
      diffTotal,
      equals(0),
      reason: 'compound block Y+U+V recon bit-exact vs SW pre-filter',
    );

    await Simulator.endSimulation();
  });
}
